import java.util.*;
import java.io.*;

public class Main {
    static class Rib {
        long b, u, c, f;
        int back;

        Rib(long b, long u, long c, long f, int back) {
            this.b = b;
            this.u = u;
            this.c = c;
            this.f = f;
            this.back = back;
        }
    }

    static void addRib(List<List<Rib>> g, long a, long b, long u, long c) {
        g.get((int) a).add(new Rib(b, u, c, 0, g.get((int) b).size()));
        g.get((int) b).add(new Rib(a, 0, -c, 0, g.get((int) a).size() - 1));
    }

    static class K {
        static long n, m, k, c, d;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Read inputs
        st = new StringTokenizer(br.readLine());
        K.n = Long.parseLong(st.nextToken());
        K.m = Long.parseLong(st.nextToken());
        K.k = Long.parseLong(st.nextToken());
        K.c = Long.parseLong(st.nextToken());

        K.d = Long.parseLong(br.readLine());

        int n = 50 * 99 + 1; // 4951
        int t = 0; // placeholder if needed

        // Initialize graph
        List<List<Rib>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            g.add(new ArrayList<>());
        }

        long s = 0, t_node = 1;

        long tim = 99;

        long[] lr = new long[55]; // 1-based indexing
        for (int i = 1; i <= K.k; i++) {
            lr[i] = Long.parseLong(br.readLine());
            addRib(g, 0, lr[i], 1, 0);
        }

        for (int j = 0; j < tim - 1; j++) {
            for (int i_idx = 2; i_idx <= K.n; i_idx++) {
                addRib(g, j * 50 + (int) i_idx, (j + 1) * 50 + (int) i_idx, 50, K.c);
            }
        }

        for (int j = 1; j < tim; j++) {
            addRib(g, j * 50 + 1, 1, 50, 0);
        }

        List<List<Long>> vr = new ArrayList<>();
        for (int i = 0; i <= K.n + 1; i++) {
            vr.add(new ArrayList<>());
        }

        for (int i = 0; i <= K.m - 1; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());

            vr.get(x).add((long) y);
            vr.get(y).add((long) x);

            for (int j_idx = 0; j_idx < tim - 1; j_idx++) {
                for (int l = 0; l < 50; l++) {
                    long cap = 1;
                    long costInc = (long) (K.c + K.d * ((l + 1) * (l + 1) - l * l));
                    addRib(g, j_idx * 50 + x, (j_idx + 1) * 50 + y, cap, costInc);
                    addRib(g, j_idx * 50 + y, (j_idx + 1) * 50 + x, cap, costInc);
                }
            }
        }

        // Implementation of min-cost max-flow
        long flow = 0;
        long cost = 0;

        while (flow < K.k) {
            int n2 = g.size();

            int[] id = new int[n2];
            long[] d = new long[n2];
            Arrays.fill(d, Long.MAX_VALUE);
            int[] q = new int[n2];
            int[] p = new int[n2];
            int[] p_rib = new int[n2];

            int qh = 0, qt = 0;
            q[qt++] = (int) s;
            d[(int) s] = 0;

            while (qh != qt) {
                int v = q[qh++];
                if (qh == n2) qh = 0;
                id[v] = 2;
                for (int i_idx = 0; i_idx < g.get(v).size(); i_idx++) {
                    Rib r = g.get(v).get(i_idx);
                    if (r.f < r.u && d[v] + r.c < d[(int) r.b]) {
                        d[(int) r.b] = d[v] + r.c;
                        p[(int) r.b] = v;
                        p_rib[(int) r.b] = i_idx;
                        if (id[(int) r.b] == 0) {
                            q[qt++] = (int) r.b;
                            if (qt == n2) qt = 0;
                        } else if (id[(int) r.b] == 2) {
                            if (--qh == -1) qh = n2 - 1;
                            q[qh] = (int) r.b;
                        }
                        id[(int) r.b] = 1;
                    }
                }
            }

            if (d[t_node] == Long.MAX_VALUE) break;

            long addFlow = K.k - flow;
            for (int v = (int) t_node; v != (int) s; v = p[v]) {
                int pv = p[v];
                int pr = p_rib[v];
                addFlow = Math.min(addFlow, g.get(pv).get(pr).u - g.get(pv).get(pr).f);
            }

            for (int v = (int) t_node; v != (int) s; v = p[v]) {
                int pv = p[v];
                int pr = p_rib[v];
                g.get(pv).get(pr).f += addFlow;
                int backIdx = g.get(pv).get(pr).back;
                g.get((int) v).get(backIdx).f -= addFlow;
                cost += g.get(pv).get(pr).c * addFlow;
            }

            flow += addFlow;
        }

        System.out.println(cost);
    }
}
